async function runSerializableTransaction(fn, maxRetries = 15) {
  let attempt = 0;
  while (true) {
    try {
      return await db.$transaction(fn, { isolationLevel: "Serializable", timeout: 3e4 });
    } catch (err) {
      attempt++;
      const error = typeof err === "object" && err !== null ? err : {};
      const isSerializationError = error.code === "P2034" || error.message?.includes("could not serialize access") || error.message?.includes("deadlock") || error.message?.includes("40001");
      if (isSerializationError && attempt < maxRetries) {
        console.warn(`[Transaction] Serialization failure on attempt ${attempt}, retrying...`);
        const delay = Math.min(200, Math.pow(2, attempt) * 10) + Math.random() * 30;
        await new Promise((res) => setTimeout(res, delay));
        continue;
      }
      throw err;
    }
  }
}
