// src/workers/payment-reconciliation.ts
init_settings();
init_ssrf_guard();
init_notifications();
init_logger();
var log11 = logger.child({ component: "PaymentReconciliation" });
async function reconcileStalePayments() {
  const tenMinutesAgo = new Date(Date.now() - 10 * 60 * 1e3);
  const twentyFourHoursAgo = new Date(Date.now() - 24 * 60 * 60 * 1e3);
  const report = {
    scanned: 0,
    reconciledSuccess: 0,
    reconciledCanceled: 0,
    orphans: 0,
    errors: 0
  };
  try {
    const stalePayments = await db.payment.findMany({
      where: {
        status: "PENDING",
        createdAt: {
          lte: tenMinutesAgo,
          gte: twentyFourHoursAgo
        }
      },
      include: {
        user: { select: { id: true, email: true } }
      },
      take: 100
    });
    report.scanned = stalePayments.length;
    if (stalePayments.length === 0) {
      log11.info("No stale PENDING payments found for reconciliation");
      return report;
    }
    log11.info(`Found ${stalePayments.length} stale PENDING payments for reconciliation`);
    const secrets = await SettingsManager.getPaymentSecrets().catch(() => null);
    const authHeader = secrets?.yookassaShopId && secrets?.yookassaSecretKey ? "Basic " + Buffer.from(`${secrets.yookassaShopId}:${secrets.yookassaSecretKey}`).toString("base64") : "Basic mock_auth";
    const reconciledItems = [];
    for (const payment of stalePayments) {
      if (!payment.gatewayId) {
        report.orphans += 1;
        log11.warn(`Stale payment ${payment.id} has no remote gatewayId`);
        continue;
      }
      if (payment.gateway === "yookassa") {
        try {
          const res = await safeFetch(`https://api.yookassa.ru/v3/payments/${payment.gatewayId}`, {
            method: "GET",
            headers: { Authorization: authHeader },
            signal: AbortSignal.timeout(1e4)
          });
          if (res.status === 404) {
            report.orphans += 1;
            log11.warn(`Payment ${payment.id} (YooKassa: ${payment.gatewayId}) not found on remote gateway`);
            continue;
          }
          if (res.ok) {
            const data = await res.json();
            if (data.status === "succeeded") {
              const realAmount = data.amount?.value ? Math.round(parseFloat(data.amount.value) * 100) : Number(payment.amount);
              await paymentService.confirmPayment(
                payment.gatewayId,
                realAmount,
                payment.userId,
                false,
                "yookassa",
                payment.id
              );
              report.reconciledSuccess += 1;
              const latencyMinutes = Math.max(1, Math.round((Date.now() - new Date(payment.createdAt).getTime()) / 6e4));
              const email = payment.user?.email || "\u043D\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u0435\u043D";
              const maskedEmail = email.includes("@") ? email.replace(/^(.{2})(.*)(@.*)$/, (_, a, b, c) => `${a}${"*".repeat(Math.min(4, b.length))}${c}`) : email;
              reconciledItems.push({
                id: payment.id,
                gatewayId: payment.gatewayId,
                maskedEmail,
                amountRub: (Number(payment.amount) / 100).toFixed(2),
                latencyMinutes
              });
              log11.info(`Reconciled succeeded payment ${payment.id} (latency: ${latencyMinutes}m)`);
            } else if (data.status === "canceled") {
              await db.payment.update({
                where: { id: payment.id },
                data: { status: "CANCELED" }
              });
              report.reconciledCanceled += 1;
              log11.info(`Reconciled canceled payment ${payment.id}`);
            }
          }
        } catch (err) {
          report.errors += 1;
          log11.error(`Failed to reconcile payment ${payment.id}`, { error: err instanceof Error ? err.message : String(err) });
        }
      }
    }
    if (reconciledItems.length > 0) {
      const itemsList = reconciledItems.map(
        (item) => `\u2022 <b>${item.amountRub} \u20BD</b> \u2014 <code>${item.maskedEmail}</code> (\u0417\u0430\u0434\u0435\u0440\u0436\u043A\u0430: <b>${item.latencyMinutes} \u043C\u0438\u043D</b>, \u0428\u043B\u044E\u0437: <code>${item.gatewayId}</code>)`
      ).join("\n");
      sendAdminAlert(
        `\u26A1 <b>[\u0410\u0432\u0442\u043E-\u0441\u0432\u0435\u0440\u043A\u0430] \u041F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u044B \u0437\u0430\u0432\u0438\u0441\u0448\u0438\u0435 \u043F\u043B\u0430\u0442\u0435\u0436\u0438 (${reconciledItems.length})</b>

\u0412\u0435\u0431\u0445\u0443\u043A\u0438 \u043D\u0435 \u043F\u043E\u0441\u0442\u0443\u043F\u0438\u043B\u0438 \u0432\u043E\u0432\u0440\u0435\u043C\u044F, \u0431\u0430\u043B\u0430\u043D\u0441\u044B \u043D\u0430\u0447\u0438\u0441\u043B\u0435\u043D\u044B \u0447\u0435\u0440\u0435\u0437 \u043E\u043F\u0440\u043E\u0441 API \u0448\u043B\u044E\u0437\u0430:

${itemsList}`,
        "WARNING"
      );
    }
    return report;
  } catch (err) {
    log11.error("Payment reconciliation job failed", { error: err instanceof Error ? err.message : String(err) });
    return report;
  }
}

// src/lib/alerts/webhook-health.ts
init_db();
init_notifications();
init_logger();
var log12 = logger.child({ component: "WebhookHealthMonitor" });
async function checkWebhookHealth() {
  const oneHourAgo = new Date(Date.now() - 60 * 60 * 1e3);
  try {
    const recentPayments = await db.payment.findMany({
      where: {
        createdAt: { gte: oneHourAgo }
      },
      select: {
        id: true,
        status: true,
        gateway: true,
        createdAt: true
      }
    });
    const pendingCount = recentPayments.filter((p) => p.status === "PENDING").length;
    const succeededCount = recentPayments.filter((p) => p.status === "SUCCEEDED").length;
    let healthy = true;
    let alertSent = false;
    if (pendingCount >= 3 && succeededCount === 0) {
      healthy = false;
      alertSent = true;
      log12.error("Silent Webhook Failure Detected: 0 successes with multiple pending payments", {
        pendingCount,
        succeededCount
      });
      sendAdminAlert(
        `\u{1F6A8} <b>CRITICAL: \u0421\u0431\u043E\u0439 \u043F\u043B\u0430\u0442\u0451\u0436\u043D\u044B\u0445 \u0432\u0435\u0431\u0445\u0443\u043A\u043E\u0432!</b>
\u0417\u0430 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u0447\u0430\u0441 \u0441\u043E\u0437\u0434\u0430\u043D\u043E ${pendingCount} \u043F\u043B\u0430\u0442\u0435\u0436\u0435\u0439, \u043D\u043E \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u043E <b>0 \u0443\u0441\u043F\u0435\u0448\u043D\u044B\u0445 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0438\u0439</b>.
\u041F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E\u0441\u0442\u044C URL \u0432\u0435\u0431\u0445\u0443\u043A\u0430 \u0438 \u043B\u043E\u0433\u0438 \u043F\u043B\u0430\u0442\u0451\u0436\u043D\u043E\u0433\u043E \u0448\u043B\u044E\u0437\u0430!`,
        "CRITICAL"
      );
    } else {
      log12.info("Webhook health check OK", { pendingCount, succeededCount });
    }
    return {
      healthy,
      pendingCount,
      succeededCount,
      alertSent
    };
  } catch (err) {
    log12.error("Failed to execute webhook health check", {
      error: err instanceof Error ? err.message : String(err)
    });
    return {
      healthy: false,
      pendingCount: 0,
      succeededCount: 0,
      alertSent: false
    };
  }
}

