init_logger();
var log17 = logger.child({ component: "CacheRevalidator" });
async function triggerCacheRevalidation(tags) {
  const secret = process.env.INTERNAL_API_SECRET;
  const baseUrl2 = process.env.NEXT_PUBLIC_APP_URL || "http://127.0.0.1:3000";
  if (!secret) {
    log17.warn("INTERNAL_API_SECRET is missing. Cache revalidation skipped. This is normal during build/dev, but critical in production.");
    return false;
  }
  try {
    const url = new URL("/api/internal/revalidate", baseUrl2).toString();
    const response = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${secret}`
      },
      body: JSON.stringify({ tags })
    });
    if (!response.ok) {
      log17.error(`Failed to revalidate tags: ${tags.join(", ")}. Status: ${response.status} ${response.statusText}`);
      return false;
    }
    log17.info(`Successfully triggered cache revalidation for tags: ${tags.join(", ")}`);
    return true;
  } catch (error) {
    log17.error(`Network error while trying to revalidate tags: ${tags.join(", ")}`, {
      error: error instanceof Error ? error.message : String(error)
    });
    return false;
  }
}

