                where: { id: s.id },
                data: {
                  isActive: false,
                  isQuarantined: true,
                  quarantinedAt: /* @__PURE__ */ new Date(),
                  quarantineReason: `Upper Sanity Limit Exceeded: Retail price ${retailRub.toFixed(2)} \u20BD > ${UPPER_SANITY_LIMIT_RUB2} \u20BD/1k`
                }
