// src/workers/processors/ai-observer.processor.ts
var log23 = logger.child({ component: "AiObserverWorker" });
async function aiObserverProcessor(job) {
  try {
    log23.info(`[${job.id}] Executing daily Executive AI Observer pipeline...`);
    const tenantId = job.data?.tenantId || "smmplan";
    const result = await AiObserverService.runObserverPipeline({
      tenantId,
      sendTelegram: true,
      forceRun: false
    });
    if (result.isKillswitchActive) {
      log23.info(`[${job.id}] AI Observer was skipped due to Master Kill-Switch.`);
      return { skipped: true, reason: "KILLSWITCH_ACTIVE" };
    }
    log23.info(`[${job.id}] Executive AI Observer completed successfully in ${result.latencyMs}ms (Source: ${result.source})`);
    return {
      success: true,
      source: result.source,
      latencyMs: result.latencyMs,
      generatedAt: result.generatedAt
    };
  } catch (error) {
    log23.error(`[${job.id}] Critical error in AI Observer worker: ${error.message}`);
    throw error;
  }
}

